import { useState, type ReactNode } from 'react';
import { BarChart3, ChefHat, ClipboardList, Clock3, Download, FileText, LayoutDashboard, LogOut, Menu as MenuIcon, Pencil, Printer, Search, Settings2, ShieldCheck, Truck, Users, UtensilsCrossed, X } from 'lucide-react';
import { useLocation } from 'wouter';
import { demoCustomers, demoOrders, popularMeals, prepTotals, weeklyAnalytics, type AdminCustomer, type AdminOrder, type AdminOrderStatus, type PaymentMethod } from '@/data/adminDemo';
import { weeklyMenu, type WeeklyMeal } from '@/data/weeklyMenu';

type AdminTab = 'Overview' | 'Orders' | 'Kitchen prep' | 'Customers' | 'Weekly menu' | 'Analytics' | 'Fulfillment' | 'Payments' | 'Settings' | 'Meal library';
type AdminMenuMeal = WeeklyMeal & { available: boolean };
const tabs: Array<{ id: AdminTab; route: string; icon: typeof LayoutDashboard }> = [
  { id: 'Overview', route: '/admin/dashboard', icon: LayoutDashboard },
  { id: 'Orders', route: '/admin/orders', icon: ClipboardList },
  { id: 'Kitchen prep', route: '/admin/kitchen-prep', icon: ChefHat },
  { id: 'Meal library', route: '/admin/meals', icon: UtensilsCrossed },
  { id: 'Weekly menu', route: '/admin/weekly-menu', icon: UtensilsCrossed },
  { id: 'Customers', route: '/admin/customers', icon: Users },
  { id: 'Analytics', route: '/admin/analytics', icon: BarChart3 },
  { id: 'Payments', route: '/admin/payments', icon: ShieldCheck },
  { id: 'Settings', route: '/admin/settings', icon: Settings2 },
];
const statuses: AdminOrderStatus[] = ['New', 'Confirmed', 'Preparing', 'Ready', 'Out for Delivery', 'Completed', 'Cancelled'];
function tabForRoute(path: string): AdminTab {
  return tabs.find((tab) => path === tab.route)?.id || 'Overview';
}
function routeForTab(tab: AdminTab) {
  return tabs.find((item) => item.id === tab)?.route || '/admin/dashboard';
}

function money(value: number) { return `$${value.toFixed(2)}`; }
function csvCell(value: string | number) { return `"${String(value).replaceAll('"', '""')}"`; }
function downloadCsv(filename: string, rows: Array<Array<string | number>>) {
  const content = rows.map((row) => row.map(csvCell).join(',')).join('\n');
  const blob = new Blob([content], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url);
}

export default function AdminApp() {
  const previewAllowed = import.meta.env.DEV || import.meta.env.VITE_ADMIN_PREVIEW === 'true';
  const [authenticated, setAuthenticated] = useState(() => previewAllowed && new URLSearchParams(window.location.search).get('preview') === '1');
  const [location, setLocation] = useLocation();
  const tab = tabForRoute(location);
  const [mobileNav, setMobileNav] = useState(false);
  const [orders, setOrders] = useState(demoOrders);
  const [selectedOrder, setSelectedOrder] = useState<AdminOrder | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<AdminCustomer | null>(null);
  const [menuMeals, setMenuMeals] = useState<AdminMenuMeal[]>(() => weeklyMenu.meals.map((meal) => ({ ...meal, available: true })));
  const [selectedPrep, setSelectedPrep] = useState<number | null>(null);

  if (!authenticated) return <AdminAuthGate previewAllowed={previewAllowed} onPreview={() => setAuthenticated(true)} />;

  function changeStatus(id: string, status: AdminOrderStatus) {
    setOrders((current) => current.map((order) => order.id === id ? { ...order, status } : order));
    setSelectedOrder((current) => current?.id === id ? { ...current, status } : current);
  }
  function markPaid(id: string) {
    setOrders((current) => current.map((order) => order.id === id ? { ...order, payment: 'Paid' } : order));
    setSelectedOrder((current) => current?.id === id ? { ...current, payment: 'Paid' } : current);
  }
  function exportOrders() {
    downloadCsv('904-weekly-orders.csv', [['Order number', 'Customer', 'Phone', 'Email', 'Meals', 'Total meals', 'Meal subtotal', 'Premium charges', 'Delivery charge', 'Final total', 'Payment method', 'Payment status', 'Fulfillment', 'Window', 'Order status', 'Order date'], ...orders.map((order) => [order.orderNumber, order.customer, order.phone, order.email, order.meals, order.mealCount, order.mealSubtotal, order.premiumCharges, order.deliveryCharge, order.total, order.paymentMethod, order.payment, order.fulfillment, order.window, order.status, order.date])]);
  }
  function exportCustomers() {
    downloadCsv('904-customers.csv', [['Name', 'Phone', 'Email', 'Address', 'Lifetime spend', 'Orders', 'Average order', 'Last order', 'Favorite meals', 'Pickup orders', 'Delivery orders'], ...demoCustomers.map((customer) => [customer.name, customer.phone, customer.email, customer.address, customer.lifetimeSpend, customer.orders, customer.averageOrder, customer.lastOrder, customer.favoriteMeals.join('; '), customer.pickupOrders, customer.deliveryOrders])]);
  }
  function exportPrep() {
    downloadCsv('904-kitchen-prep.csv', [['Meal number', 'Meal', 'Category', 'Quantity', 'Revenue'], ...prepTotals.map((meal) => [meal.mealNumber, meal.name, meal.category, meal.quantity, meal.revenue])]);
  }

  return (
    <div className="admin-shell min-h-[100dvh] bg-[#f3f5f2] text-[#173c3a]">
      <aside className={`fixed inset-y-0 left-0 z-40 w-[260px] bg-[#102d2b] px-5 py-6 text-[#f1eee6] transition-transform lg:translate-x-0 ${mobileNav ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex items-center justify-between"><a href="/" className="flex items-center gap-3" data-testid="link-admin-brand"><span className="h-12 w-9 overflow-hidden rounded-sm border border-[#e7bd32]/50 bg-[#f1eee6]"><img src="/images/brand/904-meal-prepz-logo.jpeg" alt="904 Meal Prepz logo" className="h-full w-full object-cover object-top" /></span><span className="text-sm font-extrabold leading-tight">904<br /><span className="text-[9px] tracking-[.2em]">OPS</span></span></a><button type="button" onClick={() => setMobileNav(false)} className="lg:hidden" aria-label="Close admin navigation"><X size={20} /></button></div>
        <div className="mt-12"><p className="px-3 text-[10px] font-bold uppercase tracking-[.18em] text-[#e7bd32]">Owner workspace</p><nav className="mt-4 space-y-1" aria-label="Admin navigation">{tabs.map(({ id, route, icon: Icon }) => <button key={id} type="button" onClick={() => { setLocation(route); setMobileNav(false); }} className={`flex w-full items-center gap-3 px-3 py-3 text-left text-sm font-semibold transition-colors ${tab === id ? 'bg-[#e7bd32] text-[#102d2b]' : 'text-[#f1eee6]/65 hover:bg-[#174d49] hover:text-[#f1eee6]'}`} data-testid={`admin-nav-${id.toLowerCase().replace(/\s/g, '-')}`}><Icon size={17} strokeWidth={1.8} />{id}</button>)}</nav></div>
        <div className="absolute inset-x-5 bottom-6 border-t border-[#f1eee6]/15 pt-5"><p className="text-xs text-[#f1eee6]/50">Demo workspace</p><button type="button" onClick={() => setAuthenticated(false)} className="mt-3 flex items-center gap-2 text-xs font-bold uppercase tracking-[.12em] text-[#f1eee6]/70 hover:text-[#e7bd32]" data-testid="button-admin-logout"><LogOut size={15} /> Sign out</button></div>
      </aside>
      <div className="lg:pl-[260px]">
        <header className="sticky top-0 z-30 border-b border-[#173c3a]/10 bg-[#f3f5f2]/95 px-5 py-4 backdrop-blur lg:px-8"><div className="flex items-center justify-between gap-4"><button type="button" onClick={() => setMobileNav(true)} className="lg:hidden" aria-label="Open admin navigation"><MenuIcon size={22} /></button><div><p className="hidden text-[10px] font-bold uppercase tracking-[.18em] text-[#6d817e] sm:block">Saturday, August 29, 2026</p><h1 className="text-xl font-extrabold tracking-[-.03em]">{tab}</h1></div><div className="ml-auto flex items-center gap-3"><span className="hidden items-center gap-2 rounded-full bg-[#e4eee9] px-3 py-2 text-xs font-bold text-[#27625a] sm:flex"><span className="h-2 w-2 rounded-full bg-[#35a579]" /> Live demo data</span><span className="grid h-9 w-9 place-items-center rounded-full bg-[#e7bd32] text-sm font-black">CJ</span></div></div></header>
        <main className="mx-auto max-w-[1500px] p-5 lg:p-8" data-testid="admin-dashboard">
          <div className="mb-7 flex flex-col justify-between gap-4 border-b border-[#173c3a]/10 pb-6 sm:flex-row sm:items-end"><div><p className="text-[11px] font-bold uppercase tracking-[.18em] text-[#b28b17]">Week of August 24–30</p><h2 className="mt-2 text-3xl font-extrabold tracking-[-.05em] sm:text-4xl">{tab === 'Overview' ? 'Good morning, Christian.' : tab}</h2></div><div className="flex flex-wrap gap-2"><button type="button" onClick={exportOrders} className="inline-flex items-center gap-2 border border-[#173c3a]/20 px-3 py-2 text-xs font-bold uppercase tracking-[.1em] hover:bg-white" data-testid="button-export-orders"><Download size={15} /> Export orders</button>{tab === 'Kitchen prep' && <button type="button" onClick={() => window.print()} className="inline-flex items-center gap-2 bg-[#173c3a] px-3 py-2 text-xs font-bold uppercase tracking-[.1em] text-white hover:bg-[#27625a]" data-testid="button-print-prep"><Printer size={15} /> Print prep sheet</button>}</div></div>
          <div className="mb-6 flex items-center gap-3 border border-[#d8e3dc] bg-[#edf7f1] px-4 py-3 text-sm text-[#27625a]"><ShieldCheck size={17} /><span><strong>Owner-only workspace.</strong> This preview uses seeded records. Production data is served only through the protected API.</span></div>
          {tab === 'Overview' && <Overview orders={orders} onOrderClick={setSelectedOrder} onTab={(nextTab) => setLocation(routeForTab(nextTab))} />}
          {tab === 'Orders' && <Orders orders={orders} onOrderClick={setSelectedOrder} onStatusChange={changeStatus} onMarkPaid={markPaid} />}
          {tab === 'Kitchen prep' && <KitchenPrep selectedMeal={selectedPrep} setSelectedMeal={setSelectedPrep} onExport={exportPrep} />}
          {tab === 'Customers' && <Customers selected={selectedCustomer} setSelected={setSelectedCustomer} onExport={exportCustomers} />}
          {tab === 'Weekly menu' && <MenuManager meals={menuMeals} setMeals={setMenuMeals} />}
          {tab === 'Meal library' && <MealLibrary meals={menuMeals} setMeals={setMenuMeals} />}
          {tab === 'Analytics' && <Analytics orders={orders} />}
          {tab === 'Fulfillment' && <Fulfillment orders={orders} />}
          {tab === 'Payments' && <Payments orders={orders} onMarkPaid={markPaid} />}
          {tab === 'Settings' && <SettingsPage />}
        </main>
      </div>
      {selectedOrder && <OrderDetail order={selectedOrder} onClose={() => setSelectedOrder(null)} onStatusChange={changeStatus} onMarkPaid={markPaid} />}
    </div>
  );
}

function AdminAuthGate({ previewAllowed, onPreview }: { previewAllowed: boolean; onPreview: () => void }) {
  return <div className="grid min-h-[100dvh] place-items-center bg-[#073d45] p-5 text-[#f7f4eb]"><div className="w-full max-w-[430px] border border-[#f7f4eb]/15 bg-[#0b6470] p-7 shadow-2xl sm:p-10"><a href="/" className="flex items-center gap-3" data-testid="link-admin-return"><span className="h-16 w-12 overflow-hidden rounded-sm border border-[#efb22d]/60 bg-[#f7f4eb]"><img src="/images/brand/904-meal-prepz-logo.jpeg" alt="904 Meal Prepz logo" className="h-full w-full object-cover object-top" /></span><span className="text-sm font-extrabold leading-tight">904<br /><span className="text-[9px] tracking-[.2em]">MEAL PREPZ OPS</span></span></a><p className="mt-16 text-[10px] font-bold uppercase tracking-[.18em] text-[#efb22d]">Private owner area</p><h1 className="mt-3 text-4xl font-extrabold tracking-[-.05em]">Welcome back.</h1><p className="mt-4 text-sm leading-6 text-[#f7f4eb]/65">Production access is protected by the configured identity provider. This preview does not expose customer records without authentication.</p>{previewAllowed ? <button type="button" onClick={onPreview} className="mt-8 flex w-full items-center justify-center gap-2 bg-[#efb22d] px-5 py-4 text-xs font-extrabold uppercase tracking-[.14em] text-[#073d45]" data-testid="button-admin-preview">Open seeded preview <ArrowRightIcon /></button> : <p className="mt-8 border border-[#f7f4eb]/20 px-4 py-3 text-xs leading-5 text-[#f7f4eb]/65">Connect the production admin identity provider to continue.</p>}<p className="mt-8 flex items-center gap-2 text-xs text-[#f7f4eb]/45"><ShieldCheck size={15} /> Secure access boundary / owner only</p></div></div>;
}

function Overview({ orders, onOrderClick, onTab }: { orders: AdminOrder[]; onOrderClick: (order: AdminOrder) => void; onTab: (tab: AdminTab) => void }) {
  const paidOrders = orders.filter((order) => order.payment === 'Paid');
  const pendingOrders = orders.filter((order) => order.payment !== 'Paid' && order.payment !== 'Refunded');
  const paidRevenue = paidOrders.reduce((sum, order) => sum + order.total, 0);
  const pendingAmount = pendingOrders.reduce((sum, order) => sum + order.total, 0);
  const pickupCount = orders.filter((order) => order.fulfillment === 'Pickup').length;
  const deliveryCount = orders.filter((order) => order.fulfillment === 'Delivery').length;
  const stats = [['Weekly orders', String(orders.length), 'All payment methods', ClipboardList], ['Meals sold', String(orders.reduce((sum, order) => sum + order.mealCount, 0)), 'Active orders only', UtensilsCrossed], ['Paid revenue', money(paidRevenue), 'Across all methods', BarChart3], ['Average order', money(orders.length ? orders.reduce((sum, order) => sum + order.total, 0) / orders.length : 0), 'Order value', FileText], ['Pickup orders', String(pickupCount), `${orders.length ? Math.round((pickupCount / orders.length) * 100) : 0}%`, ChefHat], ['Delivery orders', String(deliveryCount), `${orders.length ? Math.round((deliveryCount / orders.length) * 100) : 0}%`, Truck], ['Pending payment', money(pendingAmount), `${pendingOrders.length} orders to confirm`, ShieldCheck], ['Paid orders', String(paidOrders.length), `${orders.length ? Math.round((paidOrders.length / orders.length) * 100) : 0}% of orders`, Users]] as const;
  const methodTotals = orders.reduce<Record<string, number>>((result, order) => { result[order.paymentMethod] = (result[order.paymentMethod] || 0) + (order.payment === 'Paid' ? order.total : 0); return result; }, {});
  return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{stats.map(([label, value, change, Icon]) => <div key={label} className="border border-[#173c3a]/10 bg-white p-5" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#738681]">{label}</p><Icon size={17} className="text-[#b28b17]" /></div><p className="mt-6 text-3xl font-extrabold tracking-[-.05em]">{value}</p><p className="mt-2 text-xs font-semibold text-[#35a579]">{change}</p></div>)}</div><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Panel title="Revenue and order pace" eyebrow="Last 7 weeks"><div className="mt-6"><MiniBarChart data={weeklyAnalytics} /></div></Panel><Panel title="Money by payment method" eyebrow="Paid revenue"><div className="mt-6 space-y-4">{(['Square / Apple Pay', 'Cash App', 'Venmo', 'Zelle', 'Other manual'] as PaymentMethod[]).map((method) => <div key={method}><div className="mb-2 flex justify-between gap-3 text-xs font-bold"><span>{method}</span><span>{money(methodTotals[method] || 0)}</span></div><Progress label="" value={paidRevenue ? Math.round(((methodTotals[method] || 0) / paidRevenue) * 100) : 0} color={method === 'Square / Apple Pay' ? 'bg-[#174d49]' : method === 'Cash App' ? 'bg-[#35a579]' : method === 'Venmo' ? 'bg-[#5a8fc4]' : 'bg-[#e7bd32]'} /></div>)}</div><div className="mt-6 grid grid-cols-2 gap-3 border-t border-[#173c3a]/10 pt-5 text-sm"><div><p className="text-xs text-[#738681]">Pending amount</p><strong className="mt-1 block text-lg">{money(pendingAmount)}</strong></div><div><p className="text-xs text-[#738681]">Delivery revenue</p><strong className="mt-1 block text-lg">{money(orders.filter((order) => order.payment === 'Paid' && order.fulfillment === 'Delivery').reduce((sum, order) => sum + order.deliveryCharge, 0))}</strong></div></div></Panel></div><Panel title="Recent orders" eyebrow="One order system / every payment method"><div className="mt-4 overflow-x-auto"><OrderTable orders={orders.slice(0, 5)} onOrderClick={onOrderClick} compact /></div><button type="button" onClick={() => onTab('Orders')} className="mt-5 inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.12em] text-[#27625a] hover:text-[#b28b17]" data-testid="button-view-all-orders">View all orders <ArrowRightIcon /></button></Panel></div>;
}

function Orders({ orders, onOrderClick, onStatusChange, onMarkPaid }: { orders: AdminOrder[]; onOrderClick: (order: AdminOrder) => void; onStatusChange: (id: string, status: AdminOrderStatus) => void; onMarkPaid: (id: string) => void }) {
  const [query, setQuery] = useState('');
  const filtered = orders.filter((order) => `${order.orderNumber} ${order.customer} ${order.email}`.toLowerCase().includes(query.toLowerCase()));
  return <Panel title="Weekly orders" eyebrow={`${orders.length} orders / all channels`} action={<div className="relative"><Search size={15} className="absolute left-3 top-2.5 text-[#738681]" /><input value={query} onChange={(event) => setQuery(event.target.value)} className="w-56 border border-[#173c3a]/15 bg-transparent py-2 pl-9 pr-3 text-sm outline-none focus:border-[#27625a]" placeholder="Search orders" aria-label="Search orders" data-testid="input-search-orders" /></div>}><div className="mt-5 overflow-x-auto"><OrderTable orders={filtered} onOrderClick={onOrderClick} onStatusChange={onStatusChange} onMarkPaid={onMarkPaid} /></div></Panel>;
}

function OrderTable({ orders, onOrderClick, onStatusChange, onMarkPaid, compact = false }: { orders: AdminOrder[]; onOrderClick: (order: AdminOrder) => void; onStatusChange?: (id: string, status: AdminOrderStatus) => void; onMarkPaid?: (id: string) => void; compact?: boolean }) {
  return <table className="w-full min-w-[900px] text-left text-sm"><thead><tr className="border-b border-[#173c3a]/10 text-[10px] font-bold uppercase tracking-[.12em] text-[#738681]"><th className="pb-3 pr-4">Order</th><th className="pb-3 pr-4">Customer</th><th className="pb-3 pr-4">Meals</th><th className="pb-3 pr-4">Total</th><th className="pb-3 pr-4">Fulfillment</th><th className="pb-3 pr-4">Payment</th><th className="pb-3">Status</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-b border-[#173c3a]/8 last:border-0"><td className="py-4 pr-4"><button type="button" onClick={() => onOrderClick(order)} className="font-bold text-[#27625a] hover:text-[#b28b17]">{order.orderNumber}</button><span className="mt-1 block text-xs text-[#738681]">{order.date}</span></td><td className="py-4 pr-4"><p className="font-semibold">{order.customer}</p><p className="mt-1 text-xs text-[#738681]">{order.phone}</p></td><td className="max-w-[210px] py-4 pr-4 text-xs text-[#526863]">{order.meals}<span className="mt-1 block font-bold text-[#173c3a]">{order.mealCount} meals</span></td><td className="py-4 pr-4 font-bold">{money(order.total)}</td><td className="py-4 pr-4"><span className="inline-flex items-center gap-1.5 text-xs font-semibold"><span className={`h-2 w-2 rounded-full ${order.fulfillment === 'Pickup' ? 'bg-[#27625a]' : 'bg-[#e2af23]'}`} />{order.fulfillment}</span><span className="mt-1 block text-xs text-[#738681]">{order.window}</span></td><td className="py-4 pr-4"><StatusPill label={order.payment} kind={order.payment === 'Paid' ? 'green' : order.payment === 'Payment Pending' ? 'yellow' : order.payment === 'Unpaid' ? 'yellow' : 'gray'} /><span className="mt-1 block text-[10px] font-semibold text-[#738681]">{order.paymentMethod}</span>{onMarkPaid && order.payment !== 'Paid' && order.payment !== 'Refunded' && <button type="button" onClick={() => onMarkPaid(order.id)} className="mt-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#27625a] hover:text-[#b28b17]" data-testid={`button-mark-paid-${order.id}`}>Mark paid</button>}</td><td className="py-4">{onStatusChange && !compact ? <select value={order.status} onChange={(event) => onStatusChange(order.id, event.target.value as AdminOrderStatus)} className="border border-[#173c3a]/15 bg-transparent px-2 py-1.5 text-xs font-semibold outline-none" aria-label={`Update status for ${order.orderNumber}`} data-testid={`select-status-${order.id}`}>{statuses.map((status) => <option key={status}>{status}</option>)}</select> : <StatusPill label={order.status} kind={order.status === 'Completed' ? 'green' : order.status === 'New' ? 'yellow' : order.status === 'Cancelled' ? 'red' : 'gray'} />}</td></tr>)}</tbody></table>;
}

function KitchenPrep({ selectedMeal, setSelectedMeal, onExport }: { selectedMeal: number | null; setSelectedMeal: (value: number | null) => void; onExport: () => void }) {
  const selected = prepTotals.find((meal) => meal.mealNumber === selectedMeal);
  return <div className="admin-print-sheet grid gap-6 xl:grid-cols-[1fr_330px]"><Panel title="Kitchen prep summary" eyebrow="Exact quantities for this week" action={<button type="button" onClick={onExport} className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.1em] text-[#27625a]" data-testid="button-export-prep"><Download size={15} /> CSV</button>}><div className="mt-5 border border-[#d8e3dc] bg-[#edf7f1] p-4 text-sm text-[#27625a]"><ChefHat size={17} className="mb-2" /><strong>267 total meals to prep</strong><p className="mt-1 text-xs text-[#27625a]/70">Click any meal to see the customer breakdown.</p></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{prepTotals.map((meal) => <button type="button" key={meal.mealNumber} onClick={() => setSelectedMeal(meal.mealNumber)} className={`flex items-center gap-3 border p-4 text-left transition-colors ${selectedMeal === meal.mealNumber ? 'border-[#27625a] bg-[#edf7f1]' : 'border-[#173c3a]/10 bg-white hover:border-[#27625a]'}`} data-testid={`prep-meal-${meal.mealNumber}`}><span className="grid h-9 w-9 shrink-0 place-items-center bg-[#e7bd32] text-xs font-black">#{meal.mealNumber}</span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{meal.name}</strong><small className="text-xs text-[#738681]">{meal.category}</small></span><strong className="text-xl">{meal.quantity}</strong></button>)}</div></Panel><Panel title={selected ? `#${selected.mealNumber} ${selected.name}` : 'Meal breakdown'} eyebrow={selected ? 'Customers who ordered it' : 'Select a meal'}>{selected ? <div className="mt-5 space-y-3"><PrepCustomer name="Maya Johnson" quantity={selected.mealNumber === 5 ? 2 : 1} /><PrepCustomer name="Jordan Williams" quantity={selected.mealNumber === 4 ? 2 : 1} /><PrepCustomer name="Alyssa Brown" quantity={selected.mealNumber === 8 ? 1 : 2} /><PrepCustomer name="Devin Carter" quantity={selected.mealNumber === 10 ? 2 : 1} /><div className="border-t border-[#173c3a]/10 pt-4 text-sm"><div className="flex justify-between"><span>Total required</span><strong>{selected.quantity}</strong></div><div className="mt-2 flex justify-between text-[#738681]"><span>Projected revenue</span><strong>{money(selected.revenue)}</strong></div></div></div> : <div className="py-12 text-center text-sm text-[#738681]"><UtensilsCrossed size={26} className="mx-auto mb-3 opacity-50" />Choose a meal from the prep list.</div>}</Panel></div>;
}

function Customers({ selected, setSelected, onExport }: { selected: AdminCustomer | null; setSelected: (customer: AdminCustomer | null) => void; onExport: () => void }) {
  return <Panel title="Customer directory" eyebrow="5 profiles in this demo" action={<button type="button" onClick={onExport} className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.1em] text-[#27625a]" data-testid="button-export-customers"><Download size={15} /> CSV</button>}><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{demoCustomers.map((customer) => <button key={customer.id} type="button" onClick={() => setSelected(customer)} className="border border-[#173c3a]/10 bg-white p-5 text-left transition-colors hover:border-[#27625a]" data-testid={`customer-${customer.id}`}><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-full bg-[#dbe9e2] text-sm font-black text-[#27625a]">{customer.name.split(' ').map((part) => part[0]).join('')}</span>{customer.returning && <StatusPill label="Returning" kind="green" />}</div><h3 className="mt-5 font-bold">{customer.name}</h3><p className="mt-1 text-xs text-[#738681]">{customer.email}</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-[#173c3a]/10 pt-4 text-xs"><span><small className="block text-[#738681]">Lifetime spend</small><strong className="mt-1 block text-sm">{money(customer.lifetimeSpend)}</strong></span><span><small className="block text-[#738681]">Orders</small><strong className="mt-1 block text-sm">{customer.orders}</strong></span></div></button>)}</div>{selected && <div className="mt-6 border-2 border-[#27625a] bg-[#edf7f1] p-5" data-testid="customer-detail"><div className="flex justify-between"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-[#27625a]">Customer profile</p><h3 className="mt-2 text-2xl font-extrabold">{selected.name}</h3></div><button type="button" onClick={() => setSelected(null)} aria-label="Close customer detail"><X size={19} /></button></div><div className="mt-5 grid gap-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><span><small className="block text-[#738681]">Phone</small><strong>{selected.phone}</strong></span><span><small className="block text-[#738681]">Address</small><strong>{selected.address}</strong></span><span><small className="block text-[#738681]">Favorite meals</small><strong>{selected.favoriteMeals.join(', ')}</strong></span><span><small className="block text-[#738681]">Pickup / delivery</small><strong>{selected.pickupOrders} / {selected.deliveryOrders}</strong></span></div></div>}</Panel>;
}

function MenuManager({ meals, setMeals }: { meals: AdminMenuMeal[]; setMeals: (meals: AdminMenuMeal[]) => void }) {
  const [editing, setEditing] = useState<string | null>(null);
  function toggle(id: string) { setMeals(meals.map((meal) => meal.id === id ? { ...meal, available: !meal.available } : meal)); }
  return <Panel title="Weekly menu management" eyebrow="Editable demo menu" action={<button type="button" onClick={() => setEditing('new')} className="inline-flex items-center gap-2 bg-[#173c3a] px-3 py-2 text-xs font-bold uppercase tracking-[.1em] text-white" data-testid="button-add-menu-meal"><PlusIcon /> Add meal</button>}><div className="mt-5 border border-[#e7d58d] bg-[#fff9df] p-4 text-sm text-[#7b6414]"><Settings2 size={17} className="mb-2" /><strong>Next menu cutoff: Saturday, September 5 at noon</strong><p className="mt-1 text-xs text-[#7b6414]/75">Changes here are preview-only until the protected menu API is connected.</p></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead><tr className="border-b border-[#173c3a]/10 text-[10px] font-bold uppercase tracking-[.12em] text-[#738681]"><th className="pb-3">#</th><th className="pb-3">Meal</th><th className="pb-3">Category</th><th className="pb-3">Macros</th><th className="pb-3">Price</th><th className="pb-3">Availability</th><th className="pb-3">Edit</th></tr></thead><tbody>{meals.map((meal) => <tr key={meal.id} className="border-b border-[#173c3a]/8 last:border-0"><td className="py-4 font-black">#{meal.mealNumber}</td><td className="py-4"><div className="flex items-center gap-3"><img src={meal.image} alt="" className="h-10 w-10 object-cover" /><span><strong className="block">{meal.name}</strong><small className="text-xs text-[#738681]">{meal.premium ? 'Premium +$2' : 'Standard meal'}</small></span></div></td><td className="py-4 text-xs">{meal.category}</td><td className="py-4 text-xs text-[#738681]">{meal.calories} cal / {meal.protein}g protein / {meal.carbs}g carbs</td><td className="py-4 font-bold">{money(meal.price)}</td><td className="py-4"><button type="button" onClick={() => toggle(meal.id)} className={`rounded-full px-3 py-1 text-xs font-bold ${meal.available ? 'bg-[#dff3e7] text-[#277652]' : 'bg-[#f7dddd] text-[#9c4141]'}`} data-testid={`toggle-availability-${meal.id}`}>{meal.available ? 'Available' : 'Sold out'}</button></td><td className="py-4"><button type="button" onClick={() => setEditing(editing === meal.id ? null : meal.id)} className="inline-flex items-center gap-1 text-xs font-bold uppercase tracking-[.1em] text-[#27625a]"><Pencil size={14} /> {editing === meal.id ? 'Done' : 'Edit'}</button></td></tr>)}</tbody></table></div>{editing === 'new' && <div className="mt-5 border-2 border-[#27625a] bg-[#edf7f1] p-5"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#27625a]">New meal draft</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><input className="border border-[#173c3a]/15 bg-white px-3 py-2 text-sm" placeholder="Meal name" aria-label="New meal name" /><input className="border border-[#173c3a]/15 bg-white px-3 py-2 text-sm" placeholder="Category" aria-label="New meal category" /><input className="border border-[#173c3a]/15 bg-white px-3 py-2 text-sm" placeholder="Price" aria-label="New meal price" /></div><p className="mt-3 text-xs text-[#738681]">Image upload and full persistence are handled by the production menu API boundary.</p></div>}</Panel>;
}

function Analytics({ orders }: { orders: AdminOrder[] }) {
  const paidOrders = orders.filter((order) => order.payment === 'Paid');
  const pendingOrders = orders.filter((order) => order.payment !== 'Paid' && order.payment !== 'Refunded');
  const revenueByMethod = orders.reduce<Record<string, number>>((result, order) => { if (order.payment === 'Paid') result[order.paymentMethod] = (result[order.paymentMethod] || 0) + order.total; return result; }, {});
  const paidRevenue = paidOrders.reduce((sum, order) => sum + order.total, 0);
  return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Total revenue" value={money(paidRevenue)} detail="Paid orders / all methods" /><Metric label="Pending payment" value={money(pendingOrders.reduce((sum, order) => sum + order.total, 0))} detail={`${pendingOrders.length} orders need confirmation`} /><Metric label="Paid orders" value={String(paidOrders.length)} detail={`${orders.length - paidOrders.length} unpaid or pending`} /><Metric label="Average order value" value={money(orders.length ? orders.reduce((sum, order) => sum + order.total, 0) / orders.length : 0)} detail="Paid and pending orders" /></div><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Panel title="Revenue by week" eyebrow="Historical performance"><div className="mt-6"><MiniBarChart data={weeklyAnalytics} showRevenue /></div></Panel><Panel title="Revenue by payment method" eyebrow="The same order ledger"><div className="mt-6 space-y-4">{(['Square / Apple Pay', 'Cash App', 'Venmo', 'Zelle', 'Other manual'] as PaymentMethod[]).map((method) => <div key={method}><div className="mb-2 flex justify-between gap-3 text-xs font-bold"><span>{method}</span><span>{money(revenueByMethod[method] || 0)}</span></div><Progress label="" value={paidRevenue ? Math.round(((revenueByMethod[method] || 0) / paidRevenue) * 100) : 0} color={method === 'Square / Apple Pay' ? 'bg-[#174d49]' : method === 'Cash App' ? 'bg-[#35a579]' : method === 'Venmo' ? 'bg-[#5a8fc4]' : 'bg-[#e7bd32]'} /></div>)}</div></Panel></div><div className="grid gap-6 xl:grid-cols-2"><Panel title="Customer health" eyebrow="Retention signals"><div className="mt-6 space-y-6"><Progress label="Repeat customer rate" value={67} color="bg-[#174d49]" /><Progress label="New customer share" value={33} color="bg-[#e7bd32]" /><Progress label="Delivery share" value={36} color="bg-[#8c6db1]" /></div><p className="mt-7 border-t border-[#173c3a]/10 pt-5 text-xs leading-5 text-[#738681]">Lifetime spend is calculated from each customer’s orders, regardless of payment method.</p></Panel><Panel title="Top-selling meals" eyebrow="All-time units sold"><PerformanceTable rows={popularMeals.slice(0, 3)} /></Panel></div><Panel title="Popular meals history" eyebrow="Rotation intelligence"><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead><tr className="border-b border-[#173c3a]/10 text-[10px] uppercase tracking-[.12em] text-[#738681]"><th className="pb-3">Meal</th><th className="pb-3">Units sold</th><th className="pb-3">Menu appearances</th><th className="pb-3">Avg / appearance</th><th className="pb-3">Revenue generated</th><th className="pb-3">Last appeared</th></tr></thead><tbody>{popularMeals.map((meal) => <tr key={meal.name} className="border-b border-[#173c3a]/8 last:border-0"><td className="py-4 font-bold">{meal.name}</td><td className="py-4">{meal.units}</td><td className="py-4">{meal.appearances}</td><td className="py-4">{meal.average}</td><td className="py-4 font-bold">{money(meal.revenue)}</td><td className="py-4 text-[#738681]">{meal.lastAppeared}</td></tr>)}</tbody></table></div></Panel></div>;
}

function Fulfillment({ orders }: { orders: AdminOrder[] }) {
  const pickup = orders.filter((order) => order.fulfillment === 'Pickup');
  const delivery = orders.filter((order) => order.fulfillment === 'Delivery');
  const paid = orders.filter((order) => order.payment === 'Paid').length;
  const pending = orders.filter((order) => order.payment !== 'Paid' && order.payment !== 'Refunded').length;
  const refunded = orders.filter((order) => order.payment === 'Refunded').length;
  return <div className="grid gap-6 xl:grid-cols-2"><Panel title="Pickup board" eyebrow={`${pickup.length} orders / Sunday windows`}><FulfillmentList orders={pickup} type="Pickup" /></Panel><Panel title="Delivery board" eyebrow={`${delivery.length} orders / route-ready`}><FulfillmentList orders={delivery} type="Delivery" /></Panel><Panel title="Delivery zones" eyebrow="Configurable fees"><div className="mt-5 space-y-3">{weeklyMenu.deliveryZones.map((zone) => <div key={zone.id} className="flex items-center justify-between border-b border-[#173c3a]/10 pb-3 text-sm"><span>{zone.name}</span><strong>{money(zone.fee)}</strong></div>)}</div><p className="mt-5 text-xs leading-5 text-[#738681]">No live GPS routing is enabled. Group delivery orders by zone and window for Sunday/Monday runs.</p></Panel><Panel title="Payment tracking" eyebrow="One ledger / every method"><div className="mt-5 space-y-4"><Progress label="Paid" value={orders.length ? Math.round((paid / orders.length) * 100) : 0} color="bg-[#35a579]" /><Progress label="Payment pending" value={orders.length ? Math.round((pending / orders.length) * 100) : 0} color="bg-[#e7bd32]" /><Progress label="Refunded" value={orders.length ? Math.round((refunded / orders.length) * 100) : 0} color="bg-[#9d6464]" /></div><div className="mt-6 flex justify-between border-t border-[#173c3a]/10 pt-5 text-sm"><span>Square / Apple Pay</span><StatusPill label="Preferred" kind="green" /></div><p className="mt-3 text-xs leading-5 text-[#738681]">Cash App, Venmo, Zelle, and other manual payments remain in this same order ledger until the owner confirms them.</p></Panel></div>;
}

function FulfillmentList({ orders, type }: { orders: AdminOrder[]; type: 'Pickup' | 'Delivery' }) {
  return <div className="mt-5 space-y-2">{orders.map((order) => <div key={order.id} className="border border-[#173c3a]/10 bg-white p-4"><div className="flex justify-between gap-3"><div><p className="text-xs font-bold text-[#27625a]">{order.orderNumber}</p><p className="mt-1 font-bold">{order.customer}</p></div><strong>{money(order.total)}</strong></div><div className="mt-3 flex items-start gap-2 text-xs text-[#738681]"><Clock3 size={14} className="mt-0.5 shrink-0" />{order.window}</div>{type === 'Delivery' && <div className="mt-2 flex items-start gap-2 text-xs text-[#738681]"><MapPinIcon />{order.customer === 'Jordan Williams' ? 'Arlington, Jacksonville' : 'Southside, Jacksonville'}</div>}<div className="mt-3 flex justify-between border-t border-[#173c3a]/10 pt-3"><span className="text-xs text-[#738681]">{order.mealCount} meals / {order.paymentMethod} / {order.payment}</span><StatusPill label={order.status} kind={order.status === 'Completed' ? 'green' : 'gray'} /></div></div>)}</div>;
}

function OrderDetail({ order, onClose, onStatusChange, onMarkPaid }: { order: AdminOrder; onClose: () => void; onStatusChange: (id: string, status: AdminOrderStatus) => void; onMarkPaid: (id: string) => void }) {
  const manualPayment = order.paymentMethod !== 'Square / Apple Pay';
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#102d2b]/65 p-4"><div className="max-h-[90dvh] w-full max-w-[700px] overflow-y-auto bg-[#f3f5f2] shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="order-detail-heading" data-testid="order-detail"><div className="flex items-start justify-between border-b border-[#173c3a]/10 bg-white px-5 py-5 sm:px-7"><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#b28b17]">Order detail</p><h2 id="order-detail-heading" className="mt-1 text-2xl font-extrabold">{order.orderNumber}</h2><p className="mt-1 text-xs text-[#738681]">{order.date}</p></div><button type="button" onClick={onClose} aria-label="Close order detail" data-testid="button-close-order-detail"><X size={20} /></button></div><div className="space-y-5 p-5 sm:p-7"><div className="grid gap-4 sm:grid-cols-2"><Info label="Customer" value={order.customer} /><Info label="Phone / email" value={`${order.phone} / ${order.email}`} /><Info label="Fulfillment" value={`${order.fulfillment} / ${order.window}`} /><Info label="Payment method" value={order.paymentMethod} /><Info label="Payment status" value={order.payment} /></div>{manualPayment && order.payment !== 'Paid' && <div className="border border-[#e7d58d] bg-[#fff9df] p-4 text-sm text-[#7b6414]"><p className="font-bold">Payment pending — collect {money(order.total)}</p><p className="mt-2 text-xs leading-5">Send the customer the exact total through {order.paymentMethod}. Confirm the transfer here only after the funds are visible in the payment account.</p><button type="button" onClick={() => onMarkPaid(order.id)} className="mt-4 bg-[#173c3a] px-4 py-3 text-xs font-bold uppercase tracking-[.12em] text-white hover:bg-[#27625a]" data-testid="button-detail-mark-paid">Mark paid</button></div>}<div className="border border-[#173c3a]/10 bg-white p-5"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#738681]">Meals ordered</p><p className="mt-3 text-sm leading-7">{order.meals}</p></div><div className="grid gap-3 border border-[#173c3a]/10 bg-white p-5 text-sm"><div className="flex justify-between"><span>Meal subtotal</span><strong>{money(order.mealSubtotal)}</strong></div><div className="flex justify-between"><span>Premium charges</span><strong>{money(order.premiumCharges)}</strong></div><div className="flex justify-between"><span>Delivery charge</span><strong>{money(order.deliveryCharge)}</strong></div><div className="flex justify-between border-t border-[#173c3a]/10 pt-3 text-lg"><span>Final total</span><strong>{money(order.total)}</strong></div></div><div className="flex flex-col justify-between gap-3 border-t border-[#173c3a]/10 pt-5 sm:flex-row sm:items-center"><label className="text-xs font-bold uppercase tracking-[.1em]">Order status<select value={order.status} onChange={(event) => onStatusChange(order.id, event.target.value as AdminOrderStatus)} className="ml-3 border border-[#173c3a]/15 bg-transparent px-3 py-2 text-sm font-semibold normal-case tracking-normal" data-testid="select-order-detail-status">{statuses.map((status) => <option key={status}>{status}</option>)}</select></label><button type="button" onClick={onClose} className="bg-[#173c3a] px-4 py-3 text-xs font-bold uppercase tracking-[.12em] text-white">Done</button></div></div></div></div>;
}

function MealLibrary({ meals, setMeals }: { meals: AdminMenuMeal[]; setMeals: (meals: AdminMenuMeal[]) => void }) {
  return <Panel title="Meal library" eyebrow="Permanent catalog / reusable meals" action={<button type="button" className="inline-flex items-center gap-2 bg-[#173c3a] px-3 py-2 text-xs font-bold uppercase tracking-[.1em] text-white" data-testid="button-add-library-meal"><PlusIcon /> Add meal</button>}><div className="mb-5 border border-[#d8e3dc] bg-[#edf7f1] p-4 text-sm text-[#27625a]"><strong>Build once, publish weekly.</strong><p className="mt-1 text-xs text-[#27625a]/70">These meals can be offered in future menus without recreating their nutrition and pricing details.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{meals.map((meal) => <article key={meal.id} className="border border-[#173c3a]/10 bg-white p-4"><div className="flex gap-3"><img src={meal.image} alt="" className="h-16 w-16 object-cover" /><div className="min-w-0 flex-1"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#b28b17]">#{meal.mealNumber} / {meal.category}</p><h3 className="mt-1 truncate text-sm font-extrabold">{meal.name}</h3><p className="mt-1 text-xs text-[#738681]">{meal.calories} cal / {meal.protein}g protein / {meal.carbs}g carbs</p></div></div><div className="mt-4 flex items-center justify-between border-t border-[#173c3a]/10 pt-3"><strong>{money(meal.price)}</strong><div className="flex gap-3"><button type="button" onClick={() => setMeals(meals.map((item) => item.id === meal.id ? { ...item, available: !item.available } : item))} className="text-[10px] font-bold uppercase tracking-[.1em] text-[#27625a]">{meal.available ? 'Archive' : 'Restore'}</button><button type="button" className="text-[10px] font-bold uppercase tracking-[.1em] text-[#27625a]">Edit</button></div></div></article>)}</div></Panel>;
}

function Payments({ orders, onMarkPaid }: { orders: AdminOrder[]; onMarkPaid: (id: string) => void }) {
  const methods: PaymentMethod[] = ['Square / Apple Pay', 'Cash App', 'Venmo', 'Zelle', 'Other manual'];
  const paid = orders.filter((order) => order.payment === 'Paid');
  const pending = orders.filter((order) => order.payment === 'Payment Pending' || order.payment === 'Unpaid');
  return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Paid revenue" value={money(paid.reduce((sum, order) => sum + order.total, 0))} detail="All confirmed payment methods" /><Metric label="Pending payments" value={String(pending.length)} detail="Manual confirmation needed" /><Metric label="Amount pending" value={money(pending.reduce((sum, order) => sum + order.total, 0))} detail="Not included in paid revenue" /><Metric label="Refunded payments" value={String(orders.filter((order) => order.payment === 'Refunded').length)} detail="Review in provider" /></div><Panel title="Revenue by payment method" eyebrow="One normalized order ledger"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{methods.map((method) => { const methodOrders = orders.filter((order) => order.paymentMethod === method); const revenue = methodOrders.filter((order) => order.payment === 'Paid').reduce((sum, order) => sum + order.total, 0); const pendingValue = methodOrders.filter((order) => order.payment !== 'Paid' && order.payment !== 'Refunded').reduce((sum, order) => sum + order.total, 0); return <div key={method} className="border border-[#173c3a]/10 bg-white p-4"><p className="text-xs font-extrabold">{method}</p><p className="mt-5 text-2xl font-extrabold">{money(revenue)}</p><p className="mt-1 text-xs text-[#738681]">{methodOrders.length} orders / {money(pendingValue)} pending</p></div>; })}</div></Panel><Panel title="Payment queue" eyebrow="Confirm manual transfers"><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead><tr className="border-b border-[#173c3a]/10 text-[10px] uppercase tracking-[.12em] text-[#738681]"><th className="pb-3">Order</th><th className="pb-3">Customer</th><th className="pb-3">Method</th><th className="pb-3">Amount</th><th className="pb-3">Status</th><th className="pb-3">Action</th></tr></thead><tbody>{pending.map((order) => <tr key={order.id} className="border-b border-[#173c3a]/8 last:border-0"><td className="py-4 font-bold">{order.orderNumber}</td><td className="py-4">{order.customer}</td><td className="py-4">{order.paymentMethod}</td><td className="py-4 font-bold">{money(order.total)}</td><td className="py-4"><StatusPill label={order.payment} kind="yellow" /></td><td className="py-4"><button type="button" onClick={() => onMarkPaid(order.id)} className="text-[10px] font-bold uppercase tracking-[.1em] text-[#27625a] hover:text-[#b28b17]" data-testid={`button-payment-mark-paid-${order.id}`}>Mark paid</button></td></tr>)}</tbody></table></div></Panel></div>;
}

function SettingsPage() {
  const [saved, setSaved] = useState(false);
  return <Panel title="Business settings" eyebrow="Owner configuration"><div className="mb-6 border border-[#e7d58d] bg-[#fff9df] p-4 text-sm text-[#7b6414]"><Settings2 size={17} className="mb-2" /><strong>Production settings stay server-side.</strong><p className="mt-1 text-xs">This preview shows the editable shape without exposing provider credentials or secrets.</p></div><div className="grid gap-4 sm:grid-cols-2">{[['Business name', '904 Meal Prepz'], ['Phone', '(904) 555-0184'], ['Email', 'hello@904mealprepz.com'], ['Instagram', '@904mealprepz'], ['Standard meal price', '$8.00'], ['Premium meal price', '$10.00'], ['Pickup information', 'Sunday / Jacksonville'], ['Delivery zones', 'Core 904 / East Jax / Beaches']].map(([label, value]) => <label key={label} className="text-xs font-bold uppercase tracking-[.12em]">{label}<input defaultValue={value} className="mt-2 block w-full border border-[#173c3a]/15 bg-white px-3 py-3 text-sm font-normal normal-case tracking-normal outline-none focus:border-[#27625a]" /></label>)}</div><div className="mt-8 border-t border-[#173c3a]/10 pt-6"><h3 className="text-sm font-extrabold">Manual payment instructions</h3><p className="mt-1 text-xs text-[#738681]">Configure these through server environment variables before launch.</p><div className="mt-4 grid gap-4 sm:grid-cols-3">{['Cash App', 'Venmo', 'Zelle'].map((method) => <label key={method} className="text-xs font-bold uppercase tracking-[.12em]">{method}<textarea defaultValue={`${method} instructions are configured by the owner.`} className="mt-2 min-h-24 w-full border border-[#173c3a]/15 bg-white px-3 py-3 text-sm font-normal normal-case tracking-normal outline-none focus:border-[#27625a]" /></label>)}</div></div><button type="button" onClick={() => setSaved(true)} className="mt-7 bg-[#173c3a] px-5 py-3 text-xs font-bold uppercase tracking-[.12em] text-white hover:bg-[#27625a]">{saved ? 'Saved in preview' : 'Save settings'}</button></Panel>;
}

function Panel({ title, eyebrow, action, children }: { title: string; eyebrow: string; action?: ReactNode; children: ReactNode }) {
  return <section className="border border-[#173c3a]/10 bg-white p-5 lg:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#b28b17]">{eyebrow}</p><h3 className="mt-1 text-xl font-extrabold tracking-[-.03em]">{title}</h3></div>{action}</div>{children}</section>;
}
function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <div className="border border-[#173c3a]/10 bg-white p-5"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#738681]">{label}</p><p className="mt-5 text-2xl font-extrabold tracking-[-.04em]">{value}</p><p className="mt-2 text-xs font-semibold text-[#35a579]">{detail}</p></div>; }
function Progress({ label, value, color }: { label: string; value: number; color: string }) { return <div><div className="mb-2 flex justify-between text-xs font-bold"><span>{label}</span><span>{value}%</span></div><div className="h-2 bg-[#e5ebe7]"><div className={`h-full ${color}`} style={{ width: `${value}%` }} /></div></div>; }
function MiniBarChart({ data, showRevenue = false }: { data: typeof weeklyAnalytics; showRevenue?: boolean }) { const max = Math.max(...data.map((item) => showRevenue ? item.revenue : item.orders)); return <div className="flex h-48 items-end gap-2 sm:gap-4">{data.map((item) => { const value = showRevenue ? item.revenue : item.orders; return <div key={item.week} className="group flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-[10px] font-bold text-[#738681] opacity-0 transition-opacity group-hover:opacity-100">{showRevenue ? `$${(value / 1000).toFixed(1)}k` : value}</span><div className={`w-full max-w-10 bg-[#174d49] transition-all group-hover:bg-[#e7bd32] ${item === data[data.length - 1] ? 'bg-[#e7bd32]' : ''}`} style={{ height: `${Math.max(8, (value / max) * 140)}px` }} /><span className="text-[10px] text-[#738681]">{item.week.replace('2026', '')}</span></div>; })}</div>; }
function PerformanceTable({ rows }: { rows: typeof popularMeals }) { return <div className="mt-5 space-y-3">{rows.map((row, index) => <div key={row.name} className="flex items-center gap-3 border-b border-[#173c3a]/10 pb-3 last:border-0"><span className="grid h-7 w-7 place-items-center bg-[#e7bd32] text-xs font-black">{index + 1}</span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{row.name}</strong><small className="text-xs text-[#738681]">{row.appearances} menu appearances</small></span><strong>{row.units} units</strong></div>)}</div>; }
function PrepCustomer({ name, quantity }: { name: string; quantity: number }) { return <div className="flex justify-between border-b border-[#173c3a]/10 pb-3 text-sm"><span>{name}</span><strong>× {quantity}</strong></div>; }
function Info({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#738681]">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>; }
function StatusPill({ label, kind }: { label: string; kind: 'green' | 'yellow' | 'gray' | 'red' }) { const colors = { green: 'bg-[#dff3e7] text-[#277652]', yellow: 'bg-[#fff1bd] text-[#7b6414]', gray: 'bg-[#e8eeeb] text-[#526863]', red: 'bg-[#f7dddd] text-[#9c4141]' }; return <span className={`inline-flex whitespace-nowrap rounded-full px-2.5 py-1 text-[10px] font-bold ${colors[kind]}`}>{label}</span>; }
function ArrowRightIcon() { return <span aria-hidden="true">→</span>; }
function PlusIcon() { return <span aria-hidden="true" className="text-base leading-none">+</span>; }
function MapPinIcon() { return <span aria-hidden="true" className="mt-0.5 h-3 w-3 rounded-full border-2 border-current" />; }